class Solution:
    def rotate(self, nums: List[int], k: int) -> None:
        n = len(nums)
        if n <= 1:
            return
        k %= n
        if k == 0:
            return
        self.reverse(nums, 0, n - 1)
        self.reverse(nums, 0, k - 1)
        self.reverse(nums, k, n - 1)
    def reverse(self, nums: List[int], l: int, r: int) -> None:
        while l < r:
            nums[l], nums[r] = nums[r], nums[l]
            l += 1
            r -= 1

