class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        if (n <= 1) return;
        k %= n;
        if (k == 0) return;
        int count = 0;
        for (int start = 0; count < n; start++) {
            int cur = start;
            int prev = nums[start];
            do {
                int nxt = (cur + k) % n;
                int tmp = nums[nxt];
                nums[nxt] = prev;
                prev = tmp;
                cur = nxt;
                count++;
            } while (cur != start);
        }
    }
}
